55: // RenderFrameHost (RFH) exists as a child of a FrameTreeNode. When a
56: // cross-origin navigation occurs, the FrameTreeNode swaps RFHs. After
57: // swapping, the old RFH will be marked for deletion and run any unload
58: // listeners. If an IPC is sent during an unload/beforeunload listener,
59: // it's possible that it arrives after the RFH swap and has been
60: // detached from the FrameTreeNode.
61: [[nodiscard]] bool IsDetachedFrameHost(const content::RenderFrameHost* rfh) {
62:   if (!rfh)
63:     return true;
64: 
65:   // During cross-origin navigation, a RFH may be swapped out of its
66:   // FrameTreeNode with a new RFH. In these cases, it's marked for
67:   // deletion. As this pending deletion RFH won't be following future
68:   // swaps, we need to indicate that its been detached.
69:   return GetLifecycleState(rfh) == LifecycleState::kRunningUnloadHandlers;
70: }

150: WebFrameMain::WebFrameMain(content::RenderFrameHost* rfh)
151:     : frame_tree_node_id_(rfh->GetFrameTreeNodeId()),
152:       frame_token_(rfh->GetGlobalFrameToken()),
153:       render_frame_detached_(IsDetachedFrameHost(rfh)) {
154:   // Detached RFH should not insert itself in FTN lookup since it has been
155:   // swapped already.
156:   if (!render_frame_detached_)
157:     GetFrameTreeNodeIdMap().emplace(frame_tree_node_id_, this);
158: 
159:   const auto [_, inserted] = GetFrameTokenMap().emplace(frame_token_, this);
160:   DCHECK(inserted);
161: 
162:   // WebFrameMain should only be created for active or unloading frames.
163:   DCHECK(GetLifecycleState(rfh) == LifecycleState::kActive ||
164:          GetLifecycleState(rfh) == LifecycleState::kRunningUnloadHandlers);
165: }
