171: void WebFrameMain::Destroyed() {
172:   if (FromFrameTreeNodeId(frame_tree_node_id_) == this) {
173:     // WebFrameMain initialized as detached doesn't support FTN lookup and
174:     // shouldn't erase the entry.
175:     DCHECK(!render_frame_detached_ || render_frame_disposed_);
176:     GetFrameTreeNodeIdMap().erase(frame_tree_node_id_);
177:   }
178: 
179:   GetFrameTokenMap().erase(frame_token_);
180:   MarkRenderFrameDisposed();
181:   Unpin();
182: }
