190: // Should only be called when swapping frames.
191: void WebFrameMain::UpdateRenderFrameHost(content::RenderFrameHost* rfh) {
192:   GetFrameTokenMap().erase(frame_token_);
193: 
194:   // Ensure that RFH being swapped in doesn't already exist as its own
195:   // WebFrameMain instance.
196:   frame_token_ = rfh->GetGlobalFrameToken();
197:   const auto [_, inserted] = GetFrameTokenMap().emplace(frame_token_, this);
198:   DCHECK(inserted);
199: 
200:   render_frame_disposed_ = false;
201:   TeardownMojoConnection();
202:   MaybeSetupMojoConnection();
203: }

