546: // static
547: gin_helper::Handle<WebFrameMain> WebFrameMain::From(
548:     v8::Isolate* isolate,
549:     content::RenderFrameHost* rfh) {
550:   if (!rfh)
551:     return {};
552: 
553:   WebFrameMain* web_frame;
554:   switch (GetLifecycleState(rfh)) {
555:     case LifecycleState::kSpeculative:
556:     case LifecycleState::kPendingCommit:
557:       // RFH is in the process of being swapped. Need to lookup by FTN to avoid
558:       // creating dangling WebFrameMain.
559:       web_frame = FromFrameTreeNodeId(rfh->GetFrameTreeNodeId());
560:       break;
561:     case LifecycleState::kPrerendering:
562:     case LifecycleState::kActive:
563:     case LifecycleState::kInBackForwardCache:
564:       // RFH is already assigned to the FrameTreeNode and can safely be looked
565:       // up directly.
566:       web_frame = FromRenderFrameHost(rfh);
567:       break;
568:     case LifecycleState::kRunningUnloadHandlers:
569:       // Event/IPC emitted for a frame running unload handlers. Return the exact
570:       // RFH so the security origin will be accurate.
571:       web_frame = FromRenderFrameHost(rfh);
572:       break;
573:     case LifecycleState::kReadyToBeDeleted:
574:       // RFH is gone
575:       return {};
576:   }
577: 
578:   if (web_frame)
579:     return gin_helper::CreateHandle(isolate, web_frame);
580: 
581:   auto handle = gin_helper::CreateHandle(isolate, new WebFrameMain(rfh));
582: 
583:   // Prevent garbage collection of frame until it has been deleted internally.
584:   handle->Pin(isolate);
585: 
586:   return handle;

1777: void WebContents::RenderFrameDeleted(
1778:     content::RenderFrameHost* render_frame_host) {
1779:   // A RenderFrameHost can be deleted when:
1780:   // - A WebContents is removed and its containing frames are disposed.
1781:   // - An <iframe> is removed from the DOM.
1782:   // - Cross-origin navigation creates a new RFH in a separate process which
1783:   //   is swapped by content::RenderFrameHostManager.
1784: 
1785:   // WebFrameMain::FromRenderFrameHost(rfh) will use the RFH's FrameTreeNode ID
1786:   // to find an existing instance of WebFrameMain. During a cross-origin
1787:   // navigation, the deleted RFH will be the old host which was swapped out. In
1788:   // this special case, we need to also ensure that WebFrameMain's internal RFH
1789:   // matches before marking it as disposed.
1790:   auto* web_frame = WebFrameMain::FromRenderFrameHost(render_frame_host);
1791:   if (web_frame) {
1792:     // Need to directly compare frame tokens as frames pending deletion can no
1793:     // longer be looked up using content::RenderFrameHost::FromFrameToken().
1794:     if (web_frame->frame_token_ == render_frame_host->GetGlobalFrameToken()) {
1795:       web_frame->MarkRenderFrameDisposed();
1796:     }
1797:   }
1798: }
