1800: void WebContents::RenderFrameHostChanged(content::RenderFrameHost* old_host,
1801:                                          content::RenderFrameHost* new_host) {
1802:   if (new_host->IsInPrimaryMainFrame()) {
1803:     if (old_host)
1804:       old_host->GetRenderWidgetHost()->RemoveInputEventObserver(this);
1805:     if (new_host)
1806:       new_host->GetRenderWidgetHost()->AddInputEventObserver(this);
1807:   }
1808: 
1809:   // During cross-origin navigation, a FrameTreeNode will swap out its RFH.
1810:   // If an instance of WebFrameMain exists, it will need to have its RFH
1811:   // swapped as well.
1812:   //
1813:   // |old_host| can be a nullptr so we use |new_host| for looking up the
1814:   // WebFrameMain instance.
1815:   auto* web_frame =
1816:       WebFrameMain::FromFrameTreeNodeId(new_host->GetFrameTreeNodeId());
1817:   if (web_frame) {
1818:     web_frame->UpdateRenderFrameHost(new_host);
1819:   }
